// Builds the Slack message from Rizamo's overview and the week's top posts.
const o = $('Last 7 days').first().json;
const posts = $('Top posts').all().map((i) => i.json);
const n = (v) => (typeof v === 'number' ? Math.round(v).toLocaleString('en-US') : '-');
const change = (k) => {
  const x = o.kpis?.[k];
  if (!x || typeof x.previous !== 'number' || x.previous === 0) return '';
  const pct = Math.round(((x.value - x.previous) / x.previous) * 100);
  return ` (${pct >= 0 ? '+' : ''}${pct}%)`;
};
const lines = [
  `*Social this week* (${o.from} to ${o.to})`,
  `Views: ${n(o.kpis?.views?.value)}${change('views')}`,
  `Reach: ${n(o.kpis?.reach?.value)}${change('reach')}`,
  `Engagements: ${n(o.kpis?.engagements?.value)}${change('engagements')}`,
  '',
  '*Top posts*',
  ...posts.map((p, i) => `${i + 1}. ${(p.caption || 'Untitled').split('\n')[0].slice(0, 80)} (${n(p.views)} views)${p.url ? ' ' + p.url : ''}`),
];
return [{ json: { text: lines.join('\n') } }];
